# hooks only land in /etc/profile.d/.
set -u

echo "[fix-1] promoting env vars from /etc/profile.d/ to /etc/environment"
val=""
for f in /etc/profile.d/*.sh; do
    [ -f "$f" ] || continue
    found=$(grep -E "^\s*export\s+VAULT_MASTER_KEY=" "$f" | tail -1 | sed -E "s/^\s*export\s+VAULT_MASTER_KEY=//; s/^\"//; s/\"$//; s/^\x27//; s/\x27$//")
    if [ -n "$found" ]; then val="$found"; fi
done
if [ -n "$val" ] && ! grep -q "^VAULT_MASTER_KEY=" /etc/environment 2>/dev/null; then
    echo "VAULT_MASTER_KEY=$val" >> /etc/environment
    echo "  -> VAULT_MASTER_KEY promoted to /etc/environment"
fi
val=""
for f in /etc/profile.d/*.sh; do
    [ -f "$f" ] || continue
    found=$(grep -E "^\s*export\s+VAULT_RUNTIME_FILE=" "$f" | tail -1 | sed -E "s/^\s*export\s+VAULT_RUNTIME_FILE=//; s/^\"//; s/\"$//; s/^\x27//; s/\x27$//")
    if [ -n "$found" ]; then val="$found"; fi
done
if [ -n "$val" ] && ! grep -q "^VAULT_RUNTIME_FILE=" /etc/environment 2>/dev/null; then
